import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import {
  S3Client,
  PutObjectCommand,
  ListObjectsV2Command,
} from "@aws-sdk/client-s3";
import * as fs from "fs/promises";

async function main() {
  const sourceBucket = "gold-source";
  const forkCount = 3;
  const forkPrefix = "audit-fork";
  const endpoint = "REDACTED";
  const region = "REDACTED";

  const adminCredentials = {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  };

  if (!adminCredentials.accessKeyId || !adminCredentials.secretAccessKey) {
    throw new Error("Missing TIGRIS_STORAGE admin credentials");
  }

  const forkSet = await createForks(sourceBucket, forkCount, {
    prefix: forkPrefix,
    credentials: { role: "Editor" },
  });

  if (forkSet.error) {
    throw new Error(`Failed to create forks: ${forkSet.error}`);
  }

  try {
    console.log("Forks created successfully.");

    // 2. Parallel uploads
    await Promise.all(
      forkSet.forks.map(async (fork, index) => {
        const s3 = new S3Client({
          endpoint,
          region,
          credentials: {
            accessKeyId: fork.credentials.accessKeyId,
            secretAccessKey: fork.credentials.secretAccessKey,
          },
        });
        const key = `agent-${index + 1}.out`;
        console.log(`Uploading ${key} to ${fork.bucketName}...`);
        await s3.send(
          new PutObjectCommand({
            Bucket: fork.bucketName,
            Key: key,
            Body: `Hello from agent ${index + 1}`,
          })
        );
      })
    );

    console.log("Uploads completed.");

    // 3. Audit
    const adminS3 = new S3Client({
      endpoint,
      region,
      credentials: adminCredentials,
    });

    const listObjects = async (s3: S3Client, bucket: string) => {
      const res = await s3.send(new ListObjectsV2Command({ Bucket: bucket }));
      return (res.Contents?.map((c) => c.Key!) || []).sort();
    };

    const sourceKeys = await listObjects(adminS3, sourceBucket);
    console.log(`Source keys: ${JSON.stringify(sourceKeys)}`);

    // Validate source bucket
    const expectedSourceKeys = ["seed1.txt", "seed2.txt"].sort();
    if (JSON.stringify(sourceKeys) !== JSON.stringify(expectedSourceKeys)) {
      throw new Error(`Source bucket mismatch. Expected ${expectedSourceKeys}, got ${sourceKeys}`);
    }

    const forkResults = await Promise.all(
      forkSet.forks.map(async (fork, index) => {
        const forkS3 = new S3Client({
          endpoint,
          region,
          credentials: {
            accessKeyId: fork.credentials.accessKeyId,
            secretAccessKey: fork.credentials.secretAccessKey,
          },
        });
        const keys = await listObjects(forkS3, fork.bucketName);
        return { bucket: fork.bucketName, keys };
      })
    );

    // Validate isolation
    forkResults.forEach((result, index) => {
      const agentKey = `agent-${index + 1}.out`;
      const expectedKeys = ["seed1.txt", "seed2.txt", agentKey].sort();

      if (JSON.stringify(result.keys) !== JSON.stringify(expectedKeys)) {
        throw new Error(`Fork ${index} (${result.bucket}) mismatch. Expected ${expectedKeys}, got ${result.keys}`);
      }

      // Check if other agents' files are present (though the above check already covers it, the requirement asks for explicit check)
      for (let i = 1; i <= forkCount; i++) {
        if (i !== index + 1) {
          if (result.keys.includes(`agent-${i}.out`)) {
            throw new Error(`Fork ${index} contains unauthorized file agent-${i}.out`);
          }
        }
      }
    });

    // 4. Write audit report
    const report = {
      source_keys: sourceKeys,
      fork_results: forkResults,
    };

    await fs.writeFile(
      "/home/user/isolation/audit.json",
      JSON.stringify(report, null, 2),
      "utf-8"
    );
    console.log("Audit report written to /home/user/isolation/audit.json");

  } finally {
    console.log("Tearing down forks...");
    await teardownForks(forkSet);
    console.log("Teardown complete.");
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

